const prUrls = await browserjs(tabId, async () => {
  try {
    const res = await fetch('/sitemap.xml');
    const text = await res.text();

    // Check if it's a sitemapindex
    const isIndex = text.includes('<sitemapindex');
    if (isIndex) {
      const sitemaps = Array.from(text.matchAll(/<loc>(.*?)<\/loc>/g)).map(m => m[1]);
      return { isIndex: true, sitemaps };
    }

    // Extract press-release URLs
    const matches = Array.from(text.matchAll(/<loc>(https:\/\/www\.instructure\.com\/press-release\/[^<]+)<\/loc>/g)).map(m => m[1]);
    return { isIndex: false, count: matches.length, sample: matches.slice(0, 10) };
  } catch (e) {
    return { error: e.message };
  }
});

